<script setup lang="ts">import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import AppShell from'../components/AppShell.vue';import{api}from'../services/api';const route=useRoute(),type=ref('MORNING_LEAVE'),date=ref(new Date().toISOString().slice(0,10)),end=ref(date.value),reason=ref(''),handover=ref<number|null>(null),note=ref(''),users=ref<any[]>([]),msg=ref('');const types=[{title:'Nghỉ buổi sáng (1/2 ngày)',value:'MORNING_LEAVE'},{title:'Nghỉ buổi chiều (1/2 ngày)',value:'AFTERNOON_LEAVE'},{title:'Nghỉ cả ngày',value:'FULL_DAY_LEAVE'},{title:'Nghỉ phép nhiều ngày',value:'ANNUAL_LEAVE'},{title:'Đi muộn',value:'LATE'},{title:'Về sớm',value:'EARLY_LEAVE'}];onMounted(async()=>{if(route.query.type)type.value=String(route.query.type);try{users.value=(await api('/api/users')).items}catch{}});async function send(){try{await api('/api/leave-requests',{method:'POST',body:JSON.stringify({request_type:type.value,start_date:date.value,end_date:end.value,reason:reason.value,handover_to_user_id:handover.value,note:note.value,start_time:type.value==='MORNING_LEAVE'?'08:00':null,end_time:type.value==='MORNING_LEAVE'?'12:00':null})});msg.value='Yêu cầu đã được gửi để trưởng phòng phê duyệt';reason.value=''}catch(e:any){msg.value=e.message}}</script>
<template><AppShell><main class="page"><div class="title">Đăng ký nghỉ phép</div><p class="muted">Gửi yêu cầu để trưởng phòng phê duyệt</p><div class="card leave"><h3>1. Loại yêu cầu</h3><div class="typegrid"><button v-for="t in types" :class="{active:type===t.value}" @click="type=t.value">{{t.title}}</button></div><h3>2. Thời gian nghỉ</h3><div class="dates"><v-text-field v-model="date" type="date" label="Từ ngày"/><v-text-field v-model="end" type="date" label="Đến ngày"/></div><v-alert v-if="type==='MORNING_LEAVE'" color="#fdecef" class="mb-4">Bạn sẽ nghỉ từ <b>08:00 đến 12:00</b> trong ngày đã chọn.</v-alert><h3>3. Lý do nghỉ *</h3><v-textarea v-model="reason" placeholder="Ví dụ: Có việc gia đình" rows="4" counter="500"/><h3>4. Người bàn giao công việc</h3><v-select v-model="handover" :items="users" item-title="full_name" item-value="id" label="Chọn người bàn giao" clearable/><h3>5. Ghi chú thêm (nếu có)</h3><v-textarea v-model="note" rows="2"/><v-alert v-if="msg" type="info" class="mb-4">{{msg}}</v-alert><div class="buttons"><v-btn variant="outlined" color="#8b0d24">Hủy bỏ</v-btn><v-btn color="#8b0d24" @click="send">Gửi yêu cầu</v-btn></div></div></main></AppShell></template>
<style scoped>.leave{margin-top:20px}.leave h3{color:#8b0d24;margin:18px 0 12px}.typegrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.typegrid button{padding:18px 10px;border:1px solid #efd6db;border-radius:14px;background:#fff8f9}.typegrid button.active{border:2px solid #a20d2a;background:#fdecef;color:#8b0d24;font-weight:700}.dates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.buttons{display:flex;justify-content:flex-end;gap:12px}@media(max-width:700px){.typegrid{grid-template-columns:repeat(2,1fr)}.dates{grid-template-columns:1fr}}</style>
